#!/bin/zsh
# Local development build of "LTC Bridge.app" (this Mac's architecture only).
# No Xcode required — Command Line Tools are enough. To ship a release to
# everyone's in-app updater, use ./release.sh instead.
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/jonpikereally/SPMTESync/main/updates/latest.json}"
cat > Sources/LTCBridge/Version.swift <<SWIFT
// Generated by build.sh / release.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/ltcbridge-modcache"
APP="LTC Bridge.app"
mkdir -p "$CACHE" "$APP/Contents/MacOS"
cp Resources/Info.plist "$APP/Contents/Info.plist"
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" "$APP/Contents/Info.plist"
swiftc -O -target "$(uname -m)-apple-macos13" -module-cache-path "$CACHE" \
  -o "$APP/Contents/MacOS/LTCBridge" $(ls Sources/LTCBridge/*.swift)
codesign --force --sign - "$APP"
echo "Built $APP v$VERSION ($BUILT)"
